import {pathPixelFootprintContract} from './path-pixel-footprint.js';
// Match the existing radiance integrator's local specular cone model.
export const transmittedSpreadGLSL='float hbRayTransmitSpread(float spread,float ratio,float inCosine,float outCosine){return min(1.57,spread*ratio*inCosine/max(.01,outCosine));}\n';
export const opticalSpreadContract=Object.freeze({version:1,pixelProjection:pathPixelFootprintContract,model:'local specular transmission spread; same ratio/cosine model, 0.01 grazing floor and 1.57 cap as the radiance integrator',inputs:'previous/current spread, each path IOR ratio, absolute incoming/outgoing shading-normal cosines',selection:'only successful transmission changes spread; reflection/TIR retain spread',resources:'existing current cone and previous spread scalars; no extra ray query, image, uniform, buffer or readback',remaining:'curved-normal differentials, full anisotropic/rough/participating-medium footprint transport'});
